CREATE OR REPLACE FUNCTION radar_private.delete_invoice_with_effects_impl(p_invoice_id text, p_expected_invoice_version integer, p_delete_linked_asset boolean DEFAULT true, p_expected_asset_version integer DEFAULT NULL::integer, p_verification_patch jsonb DEFAULT NULL::jsonb, p_expected_verification_version integer DEFAULT NULL::integer, p_administrative_log jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_invoice public.registered_invoices%rowtype;
    v_asset public.assets%rowtype;
    v_verification public.verifications%rowtype;
begin
    select *
    into v_invoice
    from public.registered_invoices
    where id = p_invoice_id
    for update;

    if not found then
        raise exception 'NOT_FOUND: registered_invoices/%', p_invoice_id;
    end if;

    if not public.can_write_school(v_invoice.school_id) then
        raise exception 'AUTHORIZATION_DENIED: usuário sem permissão de escrita para a escola %', v_invoice.school_id;
    end if;

    if v_invoice.row_version <> p_expected_invoice_version then
        raise exception 'OPTIMISTIC_CONFLICT: registered_invoices/%', p_invoice_id;
    end if;

    if v_invoice.linked_asset_id is not null and p_delete_linked_asset then
        select *
        into v_asset
        from public.assets
        where id = v_invoice.linked_asset_id
        for update;

        if found and (p_expected_asset_version is null or v_asset.row_version <> p_expected_asset_version) then
            raise exception 'OPTIMISTIC_CONFLICT: assets/%', v_invoice.linked_asset_id;
        end if;
    end if;

    delete from public.registered_invoices
    where id = p_invoice_id
      and row_version = p_expected_invoice_version;

    if not found then
        raise exception 'OPTIMISTIC_CONFLICT: registered_invoices/%', p_invoice_id;
    end if;

    if v_asset.id is not null and p_delete_linked_asset then
        if exists (
            select 1
            from public.registered_invoices other_invoice
            where other_invoice.linked_asset_id = v_asset.id
        ) then
            raise exception 'VALIDATION_ERROR: bem ainda está vinculado a outra nota';
        end if;

        delete from public.assets
        where id = v_asset.id
          and row_version = p_expected_asset_version;

        if not found then
            raise exception 'OPTIMISTIC_CONFLICT: assets/%', v_asset.id;
        end if;
    end if;

    if p_verification_patch is not null then
        if v_invoice.verification_id is null then
            raise exception 'VALIDATION_ERROR: nota sem verificação vinculada';
        end if;

        update public.verifications
        set
            -- Merge only projections owned by the expense; preserve manual marks
            -- and bonus_result even when an old/incomplete client sends them.
            analysis = analysis || coalesce((
                select jsonb_object_agg(key, value)
                from jsonb_each(coalesce(p_verification_patch -> 'analysis', '{}'::jsonb))
                where key in ('notaFiscal', 'consAssessoria', 'encampInventario')
            ), '{}'::jsonb),
            bonification = bonification || coalesce((
                select jsonb_object_agg(key, value)
                from jsonb_each(coalesce(p_verification_patch -> 'bonification', '{}'::jsonb))
                where key in ('consAssessoria', 'consEnviada', 'encampInventario')
            ), '{}'::jsonb)
        where id = v_invoice.verification_id
          and school_id = v_invoice.school_id
          and row_version = p_expected_verification_version
        returning * into v_verification;

        if not found then
            raise exception 'OPTIMISTIC_CONFLICT: verifications/%', v_invoice.verification_id;
        end if;
    end if;

    if p_administrative_log is not null then
        if nullif(p_administrative_log ->> 'id', '') is null
            or nullif(p_administrative_log ->> 'action', '') is null then
            raise exception 'VALIDATION_ERROR: log administrativo exige id e action';
        end if;

        insert into public.administrative_logs (
            id,
            school_id,
            actor_user_id,
            user_identifier,
            profile_name,
            action,
            details,
            event_at
        ) values (
            p_administrative_log ->> 'id',
            v_invoice.school_id,
            auth.uid(),
            coalesce(p_administrative_log ->> 'user_identifier', ''),
            coalesce(p_administrative_log ->> 'profile_name', public.current_app_role(), ''),
            p_administrative_log ->> 'action',
            coalesce(p_administrative_log -> 'details', '{}'::jsonb),
            coalesce(nullif(p_administrative_log ->> 'event_at', '')::timestamptz, now())
        );
    end if;

    return jsonb_build_object(
        'deleted_invoice_id', p_invoice_id,
        'deleted_asset_id', case when v_asset.id is null or not p_delete_linked_asset then null else v_asset.id end,
        'verification', case when v_verification.id is null then null else to_jsonb(v_verification) end
    );
end
$function$

CREATE OR REPLACE FUNCTION radar_private.save_invoice_with_effects_v2_impl(p_operation_key uuid, p_invoice jsonb, p_asset jsonb DEFAULT NULL::jsonb, p_verification_patch jsonb DEFAULT NULL::jsonb, p_expected_invoice_version integer DEFAULT NULL::integer, p_expected_asset_version integer DEFAULT NULL::integer, p_expected_verification_version integer DEFAULT NULL::integer, p_administrative_log jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'radar_private'
AS $function$
declare
    v_actor_user_id uuid := auth.uid();
    v_request jsonb;
    v_request_hash text;
    v_stored_hash text;
    v_stored_result jsonb;
    v_result jsonb;
    v_log jsonb;
begin
    if p_operation_key is null then
        raise exception 'VALIDATION_ERROR: operation key é obrigatória na gravação idempotente de Nota Fiscal';
    end if;
    if v_actor_user_id is null then
        raise exception 'AUTHORIZATION_DENIED: operação idempotente exige usuário autenticado';
    end if;

    v_request := jsonb_build_object(
        'invoice', p_invoice,
        'asset', p_asset,
        'verification_patch', p_verification_patch,
        'expected_invoice_version', p_expected_invoice_version,
        'expected_asset_version', p_expected_asset_version,
        'expected_verification_version', p_expected_verification_version,
        'administrative_log', p_administrative_log
    );
    v_request_hash := md5(v_request::text);

    insert into radar_private.invoice_operation_idempotency (
        operation_name,
        operation_key,
        actor_user_id,
        request_hash
    ) values (
        'invoice:save',
        p_operation_key,
        v_actor_user_id,
        v_request_hash
    )
    on conflict (operation_name, operation_key, actor_user_id) do nothing;

    select request_hash, result
    into v_stored_hash, v_stored_result
    from radar_private.invoice_operation_idempotency
    where operation_name = 'invoice:save'
      and operation_key = p_operation_key
      and actor_user_id = v_actor_user_id
    for update;

    if v_stored_hash is distinct from v_request_hash then
        raise exception 'IDEMPOTENCY_CONFLICT: a mesma chave de intenção foi reutilizada com outro payload';
    end if;

    if v_stored_result is not null then
        return v_stored_result;
    end if;

    v_result := radar_private.save_invoice_with_effects_impl(
        p_invoice,
        p_asset,
        p_verification_patch,
        p_expected_invoice_version,
        p_expected_asset_version,
        p_expected_verification_version,
        p_administrative_log
    );

    if p_administrative_log is not null and nullif(p_administrative_log ->> 'id', '') is not null then
        select to_jsonb(log_row)
        into v_log
        from public.administrative_logs log_row
        where log_row.id = p_administrative_log ->> 'id';
    end if;

    v_result := v_result || jsonb_build_object(
        'operation_key', p_operation_key,
        'administrative_log', v_log,
        'changed_entities', jsonb_build_array(
            'registeredInvoices',
            'assets',
            'verifications',
            'administrativeLogs'
        )
    );

    update radar_private.invoice_operation_idempotency
    set result = v_result,
        completed_at = now()
    where operation_name = 'invoice:save'
      and operation_key = p_operation_key
      and actor_user_id = v_actor_user_id;

    return v_result;
end
$function$

CREATE OR REPLACE FUNCTION public.delete_unlinked_invoice_asset()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
begin
    if old.linked_asset_id is null
        or old.linked_asset_id is not distinct from new.linked_asset_id then
        return new;
    end if;

    if exists (
        select 1
        from public.registered_invoices invoice
        where invoice.linked_asset_id = old.linked_asset_id
          and invoice.id <> new.id
    ) then
        raise exception 'INTEGRITY_CONFLICT: o bem % está vinculado a outra nota', old.linked_asset_id;
    end if;

    delete from public.assets
    where id = old.linked_asset_id
      and school_id = old.school_id;

    if not found then
        raise exception 'INTEGRITY_CONFLICT: bem derivado % não localizado para desvinculação', old.linked_asset_id;
    end if;

    return new;
end
$function$

CREATE OR REPLACE FUNCTION radar_private.identify_quality_provisional_movement_impl(p_provisional_id uuid, p_expected_provisional_version integer, p_operation_key uuid, p_invoice jsonb, p_asset jsonb DEFAULT NULL::jsonb, p_verification_patch jsonb DEFAULT NULL::jsonb, p_expected_invoice_version integer DEFAULT NULL::integer, p_expected_asset_version integer DEFAULT NULL::integer, p_expected_verification_version integer DEFAULT NULL::integer, p_administrative_log jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'radar_private'
AS $function$
declare
    v_movement public.quality_provisional_movements%rowtype;
    v_result jsonb;
    v_program text := nullif(p_invoice ->> 'program_id', '');
begin
    if auth.uid() is null
        or radar_private.current_app_role() not in ('controller','federal_assistant','technical_admin')
        or p_provisional_id is null or p_operation_key is null
        or p_expected_provisional_version is null
        or nullif(p_invoice ->> 'id', '') is null then
        raise exception 'AUTHORIZATION_DENIED: identificacao exige identidade, versao e operacao validas';
    end if;

    select * into v_movement
    from public.quality_provisional_movements
    where id = p_provisional_id
    for update;

    if not found then
        raise exception 'NOT_FOUND: movimentacao provisoria nao localizada';
    end if;
    if not radar_private.can_write_school(v_movement.school_id) then
        raise exception 'AUTHORIZATION_DENIED: escola fora do escopo de escrita';
    end if;

    if v_movement.school_id is distinct from p_invoice ->> 'school_id'
        or v_movement.competence_id is distinct from p_invoice ->> 'competence_id'
        or v_program not in ('CONECTADA', 'PROEC', 'ED_FAMILIA', 'ADOLESCENCIAS', 'LEITURA', 'TEMPO_APRENDER')
        or not exists (
            select 1 from public.school_programs sp
            where sp.school_id = v_movement.school_id
              and sp.program_id = v_program and sp.active
        )
        or p_invoice ->> 'expense_type' not in ('consumo', 'permanente', 'servico', 'boleto_internet')
    then
        raise exception 'VALIDATION_ERROR: identificacao incompatível com escola, competencia, programa ou tipo';
    end if;

    if v_movement.status = 'identified' then
        if v_movement.identification_operation_key is distinct from p_operation_key
            or v_movement.registered_invoice_id is distinct from p_invoice ->> 'id'
        then
            raise exception 'OPTIMISTIC_CONFLICT: movimentacao ja identificada';
        end if;
    elsif v_movement.row_version <> p_expected_provisional_version then
        raise exception 'OPTIMISTIC_CONFLICT: registro provisório modificado por outra sessao';
    end if;

    if v_movement.status = 'open' and (
        p_expected_invoice_version is not null
        or exists (select 1 from public.registered_invoices where id = p_invoice ->> 'id')
    ) then
        raise exception 'VALIDATION_ERROR: identificacao exige um novo documento fiscal';
    end if;

    v_result := radar_private.save_invoice_with_effects_v2_impl(
        p_operation_key, p_invoice, p_asset, p_verification_patch,
        p_expected_invoice_version, p_expected_asset_version,
        p_expected_verification_version, p_administrative_log
    );

    if v_movement.status = 'open' then
        update public.quality_provisional_movements
        set status = 'identified',
            registered_invoice_id = p_invoice ->> 'id',
            identification_operation_key = p_operation_key
        where id = p_provisional_id;
    end if;

    return v_result || jsonb_build_object(
        'quality_provisional_id', p_provisional_id,
        'quality_provisional_status', 'identified'
    );
end;
$function$

CREATE OR REPLACE FUNCTION radar_private.protect_inventoried_asset_terminal_state()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'radar_private'
AS $function$
begin
    if old.status = 'Inventariada' then
        if tg_op = 'DELETE' then
            raise exception 'ASSET_ALREADY_INVENTORIED: assets/%', old.id;
        end if;
        if new.status is distinct from old.status then
            raise exception 'ASSET_ALREADY_INVENTORIED: assets/%', old.id;
        end if;
    end if;
    if tg_op = 'DELETE' then return old; end if;
    return new;
end
$function$

CREATE OR REPLACE FUNCTION radar_private.protect_service_advisory_invoice_history()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'radar_private'
AS $function$
declare
    v_has_individual_history boolean;
    v_has_advisory_history boolean;
begin
    select
        bool_or(document_key in ('consAssessoria', 'notaFiscal')),
        bool_or(document_key = 'consAssessoria')
      into v_has_individual_history, v_has_advisory_history
      from public.pendencies
     where registered_invoice_id = old.id;

    if not coalesce(v_has_individual_history, false) then
        if tg_op = 'DELETE' then return old; end if;
        return new;
    end if;

    if tg_op = 'DELETE' then
        raise exception 'INTEGRITY_CONFLICT: Nota Fiscal possui histórico de pendência individual e não pode ser excluída';
    end if;

    if new.school_id is distinct from old.school_id
        or new.competence_id is distinct from old.competence_id
        or new.program_id is distinct from old.program_id then
        raise exception 'INTEGRITY_CONFLICT: Nota Fiscal possui histórico de pendência individual e não pode alterar escola, competência ou programa';
    end if;

    if new.expense_type is distinct from old.expense_type
        and coalesce(v_has_advisory_history, false) then
        raise exception 'INTEGRITY_CONFLICT: Nota Fiscal possui histórico de pendência da Assessoria e deve permanecer como prestação de serviço';
    end if;

    return new;
end
$function$

CREATE OR REPLACE FUNCTION public.retify_verification_with_pendency_cancel(p_verification jsonb, p_expected_verification_version integer, p_pendency jsonb, p_expected_pendency_version integer, p_administrative_log jsonb, p_retification jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare
    v_role text := public.current_app_role();
    v_verification_id text := nullif(p_verification ->> 'id', '');
    v_pendency_id text := nullif(p_pendency ->> 'id', '');
    v_school_id text;
    v_document_key text;
    v_requested_analysis text;
    v_previous_analysis text;
    v_justification text;
    v_event_at timestamptz;
    v_user_identifier text;
    v_profile_name text;
    v_existing_verification public.verifications%rowtype;
    v_existing_pendency public.pendencies%rowtype;
    v_saved_verification public.verifications%rowtype;
    v_saved_pendency public.pendencies%rowtype;
    v_log public.administrative_logs%rowtype;
    v_history jsonb;
    v_cancel_event jsonb;
    v_cancellation jsonb;
    v_next_payload jsonb;
begin
    if v_role not in ('controller', 'federal_assistant', 'technical_admin') then
        raise exception 'AUTHORIZATION_DENIED: perfil sem permissão para retificar avaliações';
    end if;

    if jsonb_typeof(p_verification) <> 'object'
        or v_verification_id is null
        or jsonb_typeof(p_pendency) <> 'object'
        or v_pendency_id is null then
        raise exception 'VALIDATION_ERROR: verificação e pendência canônicas são obrigatórias';
    end if;

    if p_expected_verification_version is null or p_expected_pendency_version is null then
        raise exception 'VALIDATION_ERROR: retificação exige versões esperadas da verificação e da pendência';
    end if;

    if p_retification is null or jsonb_typeof(p_retification) <> 'object' then
        raise exception 'VALIDATION_ERROR: confirmação formal da retificação é obrigatória';
    end if;
    if coalesce((p_retification ->> 'confirmed')::boolean, false) is distinct from true then
        raise exception 'RETIFICATION_CONFIRMATION_REQUIRED: confirmação expressa é obrigatória';
    end if;
    if nullif(p_retification ->> 'kind', '') is distinct from 'retificacao_avaliacao'
        or nullif(p_retification ->> 'origin', '') is distinct from 'avaliacao_tecnica' then
        raise exception 'VALIDATION_ERROR: tipo ou origem da retificação inválidos';
    end if;
    v_justification := nullif(btrim(p_retification ->> 'justification'), '');
    if v_justification is null then
        raise exception 'RETIFICATION_JUSTIFICATION_REQUIRED: justificativa da retificação é obrigatória';
    end if;

    if p_administrative_log is null
        or jsonb_typeof(p_administrative_log) <> 'object'
        or nullif(p_administrative_log ->> 'id', '') is null
        or nullif(p_administrative_log ->> 'action', '') is null
        or not public.radar_jsonb_matches(
            'auditDetails', coalesce(p_administrative_log -> 'details', '{}'::jsonb)
        ) then
        raise exception 'VALIDATION_ERROR: log administrativo obrigatório e inválido';
    end if;

    if not public.radar_jsonb_matches(
        'analysis', coalesce(p_verification -> 'analysis', '{}'::jsonb)
    ) or not public.radar_jsonb_matches(
        'bonification', coalesce(p_verification -> 'bonification', '{}'::jsonb)
    ) or not public.radar_jsonb_matches(
        'compatibilityPayload', coalesce(p_verification -> 'payload', '{}'::jsonb)
    ) then
        raise exception 'VALIDATION_ERROR: verificação incompatível';
    end if;

    if not public.radar_jsonb_matches(
        'compatibilityPayload', coalesce(p_pendency -> 'payload', '{}'::jsonb)
    ) then
        raise exception 'VALIDATION_ERROR: payload da pendência incompatível';
    end if;

    select *
    into v_existing_verification
    from public.verifications
    where id = v_verification_id
    for update;

    if not found then
        raise exception 'NOT_FOUND: verifications/%', v_verification_id;
    end if;

    select *
    into v_existing_pendency
    from public.pendencies
    where id = v_pendency_id
    for update;

    if not found then
        raise exception 'NOT_FOUND: pendencies/%', v_pendency_id;
    end if;

    if v_existing_verification.row_version <> p_expected_verification_version then
        raise exception 'OPTIMISTIC_CONFLICT: verifications/%', v_verification_id;
    end if;
    if v_existing_pendency.row_version <> p_expected_pendency_version then
        raise exception 'OPTIMISTIC_CONFLICT: pendencies/%', v_pendency_id;
    end if;

    v_school_id := v_existing_verification.school_id;
    v_document_key := v_existing_pendency.document_key;
    v_previous_analysis := nullif(v_existing_verification.analysis ->> v_document_key, '');
    v_requested_analysis := nullif(p_verification -> 'analysis' ->> v_document_key, '');

    if not public.can_write_school(v_school_id) then
        raise exception 'AUTHORIZATION_DENIED: usuário sem escrita para a escola %', v_school_id;
    end if;

    if v_existing_pendency.school_id is distinct from v_school_id
        or v_existing_pendency.competence_origin is distinct from v_existing_verification.competence_id
        or v_existing_pendency.program_id is distinct from v_existing_verification.program_id then
        raise exception 'VALIDATION_ERROR: verificação e pendência pertencem a contextos diferentes';
    end if;

    if nullif(p_verification ->> 'school_id', '') is distinct from v_existing_verification.school_id
        or nullif(p_verification ->> 'competence_id', '') is distinct from v_existing_verification.competence_id
        or nullif(p_verification ->> 'program_id', '') is distinct from v_existing_verification.program_id then
        raise exception 'VALIDATION_ERROR: contexto da verificação não pode ser alterado';
    end if;

    if nullif(p_pendency ->> 'school_id', '') is distinct from v_existing_pendency.school_id
        or nullif(p_pendency ->> 'competence_origin', '') is distinct from v_existing_pendency.competence_origin
        or nullif(p_pendency ->> 'program_id', '') is distinct from v_existing_pendency.program_id
        or nullif(p_pendency ->> 'document_key', '') is distinct from v_existing_pendency.document_key
        or nullif(p_pendency ->> 'registered_invoice_id', '') is distinct from v_existing_pendency.registered_invoice_id then
        raise exception 'VALIDATION_ERROR: contexto da pendência não pode ser alterado';
    end if;

    if v_document_key in ('notaFiscal', 'boletoInternet', 'consAssessoria') then
        raise exception 'VALIDATION_ERROR: documento possui fluxo técnico derivado e não admite retificação agregada';
    end if;

    if v_existing_pendency.status not in ('Aberta', 'Aguardando reanálise') then
        raise exception 'INVALID_TRANSITION: somente pendência ativa pode ser anulada por retificação';
    end if;

    if v_previous_analysis is distinct from 'Incorreto' then
        raise exception 'INVALID_TRANSITION: análise atual precisa ser Incorreto para anular pendência por retificação';
    end if;

    if nullif(p_pendency ->> 'status', '') is distinct from 'Cancelada' then
        raise exception 'INVALID_TRANSITION: retificação com pendência ativa deve resultar em estado técnico Cancelada';
    end if;

    if v_requested_analysis not in ('Não analisado', 'Correto', 'Correto (Atrasado)') then
        raise exception 'VALIDATION_ERROR: estado técnico de destino inválido para retificação';
    end if;

    if nullif(p_retification ->> 'previousAnalysis', '') is distinct from v_previous_analysis
        or nullif(p_retification ->> 'newAnalysis', '') is distinct from v_requested_analysis then
        raise exception 'VALIDATION_ERROR: confirmação não corresponde à alteração efetivamente solicitada';
    end if;

    if coalesce(p_verification -> 'bonification', '{}'::jsonb) is distinct from v_existing_verification.bonification
        or nullif(p_verification ->> 'bonus_result', '') is distinct from v_existing_verification.bonus_result
        or coalesce(p_verification -> 'payload', '{}'::jsonb) is distinct from v_existing_verification.payload then
        raise exception 'VALIDATION_ERROR: retificação técnica não pode alterar bonificação, consolidação ou payload da verificação';
    end if;

    if (coalesce(p_verification -> 'analysis', '{}'::jsonb) - v_document_key)
        is distinct from (v_existing_verification.analysis - v_document_key) then
        raise exception 'VALIDATION_ERROR: retificação técnica não pode alterar a análise de outros documentos';
    end if;

    if coalesce(p_pendency ->> 'responsible_area', '') is distinct from v_existing_pendency.responsible_area
        or coalesce(p_pendency ->> 'reason', '') is distinct from v_existing_pendency.reason
        or coalesce(p_pendency ->> 'notes', '') is distinct from v_existing_pendency.notes then
        raise exception 'VALIDATION_ERROR: anulação por retificação não pode editar dados cadastrais da pendência';
    end if;

    if v_requested_analysis = 'Correto'
        and lower(coalesce(v_existing_verification.bonus_result, '')) in ('apta', 'inapta')
        and coalesce(v_existing_verification.bonification ->> v_document_key, '') = 'Não' then
        raise exception 'LATE_ANALYSIS_REQUIRED: documento exige Correto (Atrasado) após não entrega consolidada';
    end if;

    v_event_at := coalesce(
        nullif(p_administrative_log ->> 'event_at', '')::timestamptz,
        now()
    );
    v_user_identifier := coalesce(
        nullif(p_administrative_log ->> 'user_identifier', ''),
        auth.uid()::text,
        'Sistema'
    );
    v_profile_name := coalesce(
        nullif(p_administrative_log ->> 'profile_name', ''),
        v_role,
        'sistema'
    );

    v_history := case
        when jsonb_typeof(v_existing_pendency.payload -> 'historico') = 'array'
            then v_existing_pendency.payload -> 'historico'
        else '[]'::jsonb
    end;
    v_cancel_event := jsonb_build_object(
        'id', 'evento-retificacao-' || (p_administrative_log ->> 'id'),
        'tipo', 'retificacao_avaliacao',
        'dataHora', v_event_at,
        'usuario', v_user_identifier,
        'perfil', v_profile_name,
        'detalhe', format(
            'Avaliação técnica retificada de "%s" para "%s". Pendência anulada por edição da avaliação. Justificativa: %s',
            v_previous_analysis,
            v_requested_analysis,
            v_justification
        ),
        'erros', case
            when jsonb_typeof(v_existing_pendency.payload -> 'errosAtuais') = 'array'
                then v_existing_pendency.payload -> 'errosAtuais'
            else '[]'::jsonb
        end,
        'tentativaId', null,
        'metadados', jsonb_build_object(
            'tipoEncerramento', 'retificacao_avaliacao',
            'origem', 'avaliacao_tecnica',
            'avaliacaoAnterior', v_previous_analysis,
            'avaliacaoNova', v_requested_analysis,
            'confirmacaoExpressa', true
        )
    );
    v_cancellation := jsonb_build_object(
        'tipo', 'retificacao_avaliacao',
        'origem', 'avaliacao_tecnica',
        'rotulo', 'Anulada por edição da avaliação',
        'avaliacaoAnterior', v_previous_analysis,
        'avaliacaoNova', v_requested_analysis,
        'justificativa', v_justification,
        'confirmacaoExpressa', true,
        'dataHora', v_event_at,
        'usuario', v_user_identifier,
        'perfil', v_profile_name
    );
    v_next_payload := v_existing_pendency.payload || jsonb_build_object(
        'status', 'Cancelada',
        'proximoAtor', null,
        'dataResolucao', null,
        'cancelamento', v_cancellation,
        'historico', v_history || jsonb_build_array(v_cancel_event)
    );

    update public.verifications
    set analysis = jsonb_set(
        v_existing_verification.analysis,
        array[v_document_key],
        to_jsonb(v_requested_analysis),
        true
    )
    where id = v_verification_id
      and row_version = p_expected_verification_version
    returning * into v_saved_verification;

    if not found then
        raise exception 'OPTIMISTIC_CONFLICT: verifications/%', v_verification_id;
    end if;

    update public.pendencies
    set
        status = 'Cancelada',
        next_actor = '',
        resolved_at = null,
        canceled_at = v_event_at,
        payload = v_next_payload
    where id = v_pendency_id
      and row_version = p_expected_pendency_version
    returning * into v_saved_pendency;

    if not found then
        raise exception 'OPTIMISTIC_CONFLICT: pendencies/%', v_pendency_id;
    end if;

    if nullif(p_administrative_log ->> 'school_id', '') is not null
        and (p_administrative_log ->> 'school_id') is distinct from v_school_id then
        raise exception 'VALIDATION_ERROR: log administrativo pertence a outra escola';
    end if;

    insert into public.administrative_logs (
        id,
        school_id,
        actor_user_id,
        user_identifier,
        profile_name,
        action,
        details,
        event_at
    ) values (
        p_administrative_log ->> 'id',
        v_school_id,
        auth.uid(),
        coalesce(p_administrative_log ->> 'user_identifier', ''),
        v_profile_name,
        p_administrative_log ->> 'action',
        coalesce(p_administrative_log -> 'details', '{}'::jsonb),
        v_event_at
    )
    returning * into v_log;

    return jsonb_build_object(
        'verification', to_jsonb(v_saved_verification),
        'pendency', to_jsonb(v_saved_pendency),
        'administrative_log', to_jsonb(v_log)
    );
end
$function$
